from typing import List

class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        ans = -1
        for i in range(1, len(nums) - 1):
            j = i
            l = 2
            while j < len(nums) and nums[j] - nums[j - 1] == (-1) ** l:
                ans = max(ans, l)
                j += 1
                l += 1
        return ans

